# ===== server.py =====
TEXT_FILES['server.py'] = r'''"""Local Python web application. python server.py [--port 8765] [--open]."""
import argparse
import json
import os
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit
import webbrowser

import core

ROOT = Path(__file__).resolve().parent / 'dist'


class Handler(SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(ROOT), **kwargs)

    def end_headers(self):
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Referrer-Policy', 'no-referrer')
        self.send_header('Cache-Control', 'no-cache')
        super().end_headers()

    def do_GET(self):
        if urlsplit(self.path).path == '/api/health':
            self.reply(200, {'engine': 'python', 'version': 1, 'storage': 'browser-local'})
        else:
            super().do_GET()

    def reply(self, status, value):
        data = json.dumps(value, ensure_ascii=False).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):
        if urlsplit(self.path).path != '/api/engine':
            self.reply(404, {'error': '接口不存在'})
            return
        # Same-origin only; no CORS or remote ledger writes.
        origin = self.headers.get('Origin')
        if origin and urlsplit(origin).netloc != self.headers.get('Host'):
            self.reply(403, {'error': '只允许当前网页请求'})
            return
        try:
            size = int(self.headers.get('Content-Length', 0))
            if not 0 < size <= 16 * 1024 * 1024:
                raise ValueError('请求文件为空或超过 16 MB')
            request = json.loads(self.rfile.read(size))
            if not isinstance(request, dict):
                raise ValueError('请求格式无效')
            self.reply(200, core.api(request))
        except (ValueError, TypeError, KeyError) as error:
            self.reply(400, {'error': str(error)})

    def log_message(self, fmt, *args):
        # Never print request bodies or personal financial data.
        if args and '/api/' not in str(args[0]):
            super().log_message(fmt, *args)


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--port', type=int, default=8765)
    parser.add_argument('--open', action='store_true')
    options = parser.parse_args()
    try:
        server = ThreadingHTTPServer(('127.0.0.1', options.port), Handler)
    except OSError:
        raise SystemExit(f'Port {options.port} is busy. Use --port with a different port.')
    url = f'http://127.0.0.1:{options.port}'
    print(f'Meow Ledger / Python business engine\nLocal: {url}\nCtrl+C to stop', flush=True)
    if options.open:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        server.server_close()
'''

# ===== storage.py =====
TEXT_FILES['storage.py'] = '"""Transactional desktop ledger. Amounts remain integer cents."""\nimport json\nimport sqlite3\nimport threading\nfrom contextlib import contextmanager\nfrom datetime import datetime\nfrom pathlib import Path\nimport core\n\n\nclass LedgerStore:\n    def __init__(self, directory):\n        self.directory = Path(directory)\n        self.directory.mkdir(parents=True, exist_ok=True)\n        self.path = self.directory / \'ledger.sqlite3\'\n        self.lock = threading.RLock()\n        with self.connect() as db:\n            db.executescript(\'\'\'\n                CREATE TABLE IF NOT EXISTS metadata (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);\n                INSERT OR IGNORE INTO metadata VALUES (1,0);\n                CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, body TEXT NOT NULL);\n                CREATE TABLE IF NOT EXISTS budgets (month TEXT PRIMARY KEY, cents INTEGER NOT NULL CHECK(cents>0));\n                CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);\n            \'\'\')\n            db.execute(\'INSERT OR IGNORE INTO settings VALUES (1,?)\',\n                       (json.dumps(core.empty_state()[\'settings\']),))\n\n    @contextmanager\n    def connect(self):\n        db = sqlite3.connect(self.path, timeout=10)\n        db.execute(\'PRAGMA journal_mode=WAL\')\n        db.execute(\'PRAGMA synchronous=FULL\')\n        try:\n            with db:\n                yield db\n        finally:\n            db.close()\n\n    @staticmethod\n    def read(db):\n        state = core.empty_state()\n        state[\'transactions\'] = [json.loads(row[0]) for row in db.execute(\'SELECT body FROM transactions ORDER BY id\')]\n        state[\'budgets\'] = dict(db.execute(\'SELECT month,cents FROM budgets\'))\n        state[\'settings\'] = json.loads(db.execute(\'SELECT body FROM settings WHERE id=1\').fetchone()[0])\n        revision = db.execute(\'SELECT revision FROM metadata WHERE id=1\').fetchone()[0]\n        return core.validate_state(state), revision\n\n    def snapshot(self):\n        with self.lock, self.connect() as db:\n            state, revision = self.read(db)\n            return {\'state\': state, \'revision\': revision}\n\n    def action(self, action, payload, expected_revision, month=None, filters=None):\n        with self.lock, self.connect() as db:\n            db.execute(\'BEGIN IMMEDIATE\')\n            state, revision = self.read(db)\n            if type(expected_revision) is not int or revision != expected_revision:\n                raise ValueError(\'账本已变化，请重新打开页面后再保存，避免覆盖数据\')\n            next_state = core.apply_action(state, action, payload)\n            # Write the recovery file before an explicit replacement transaction.\n            backup = None\n            if action == \'import\' and payload.get(\'mode\') == \'replace\':\n                folder = self.directory / \'backups\'\n                folder.mkdir(exist_ok=True)\n                backup = folder / (\'覆盖前备份-\' + datetime.now().strftime(\'%Y%m%d-%H%M%S-%f\') + \'.json\')\n                with backup.open(\'x\', encoding=\'utf-8\') as out:\n                    json.dump(state, out, ensure_ascii=False, indent=2)\n                    out.flush()\n                    import os\n                    os.fsync(out.fileno())\n            db.execute(\'DELETE FROM transactions\')\n            db.executemany(\'INSERT INTO transactions VALUES (?,?)\',\n                           [(t[\'id\'], json.dumps(t, ensure_ascii=False)) for t in next_state[\'transactions\']])\n            db.execute(\'DELETE FROM budgets\')\n            db.executemany(\'INSERT INTO budgets VALUES (?,?)\', next_state[\'budgets\'].items())\n            db.execute(\'UPDATE settings SET body=? WHERE id=1\', (json.dumps(next_state[\'settings\']),))\n            db.execute(\'UPDATE metadata SET revision=? WHERE id=1\', (revision + 1,))\n            result = {\'state\': next_state, \'revision\': revision + 1, \'backup\': str(backup) if backup else None}\n            if month:\n                result[\'analysis\'] = core.analyze(next_state, month)\n                result[\'filteredAnalysis\'] = core.analyze(next_state, month, filters)\n            return result\n'

# ===== windows_settings.py =====
TEXT_FILES['windows_settings.py'] = r'''"""Current-user Windows integration; no elevation or global startup entries."""
import os
import sys
import subprocess
from pathlib import Path
import winreg

RUN_KEY = r'Software\Microsoft\Windows\CurrentVersion\Run'
RUN_NAME = 'MeowLedger'


def startup_command():
    if getattr(sys, 'frozen', False):
        return subprocess.list2cmdline([sys.executable, '--autostart'])
    return subprocess.list2cmdline([sys.executable, str(Path(__file__).with_name('desktop.py')), '--autostart'])


def read_startup():
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, RUN_KEY) as key:
            value, _ = winreg.QueryValueEx(key, RUN_NAME)
    except FileNotFoundError:
        return {'enabled': False, 'configured': False}
    return {'enabled': value == startup_command(), 'configured': True}


def set_startup(enabled):
    if type(enabled) is not bool:
        raise ValueError('自启动开关必须是布尔值')
    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, RUN_KEY) as key:
        if enabled:
            winreg.SetValueEx(key, RUN_NAME, 0, winreg.REG_SZ, startup_command())
        else:
            try:
                winreg.DeleteValue(key, RUN_NAME)
            except FileNotFoundError:
                pass
    status = read_startup()
    if status['enabled'] != enabled or (not enabled and status['configured']):
        raise OSError('无法确认系统自启动状态，请检查当前用户权限')
    return status
'''

# ===== 安装须知.txt =====
TEXT_FILES['安装须知.txt'] = r'''记账喵 1.0.0 - 本地优先的生活费记账伙伴

此安装程序只安装到当前 Windows 用户，不需要管理员权限。
支持 Windows 10/11 64 位。运行需要系统 Microsoft Edge WebView2 运行时和 .NET Framework 4.6.2 或更高版本。
安装包已包含 Python 运行环境，不需要用户另装 Python、Node 或设计软件。

记账功能不依赖互联网。默认关闭开机自启动，设置页中可主动开启。
桌面账本保存到当前用户 LocalAppData\MeowLedger\ledger.sqlite3。
网页、手机和桌面账本分别保存，不自动同步。原网页账本请导出 JSON 后导入桌面版。
卸载会移除程序、快捷方式和本应用自启动项，但保留账本和自动备份。
请定期从设置页导出 JSON 备份。

手机使用的是另行提供的响应式网页/PWA，需要 HTTPS 部署地址，不能运行此 EXE。
此版本尚未公开部署手机网页，也未对安装程序进行代码签名。
'''

