def resource_bytes():
    data = base64.b64decode(ASSET_ZIP_B64)
    if hashlib.sha256(data).hexdigest() != ASSET_SHA256:
        raise ValueError('人物资源校验失败，源码文件可能不完整')
    return data


def self_check():
    for name, text in TEXT_FILES.items():
        if name.endswith('.py'):
            compile(text, name, 'exec')
    with zipfile.ZipFile(io.BytesIO(resource_bytes())) as archive:
        bad = archive.testzip()
        if bad:
            raise ValueError('资源损坏：' + bad)
        return {'version': VERSION, 'pythonModules': sum(n.endswith('.py') for n in TEXT_FILES),
                'textFiles': len(TEXT_FILES), 'binaryResources': len(archive.namelist()), 'valid': True}


def extract_source(destination):
    destination = Path(destination).expanduser()
    destination.mkdir(parents=True, exist_ok=True)
    destination = destination.resolve()
    def safe_path(name):
        target = (destination / name).resolve()
        if not target.is_relative_to(destination):
            raise ValueError('无效资源路径')
        target.parent.mkdir(parents=True, exist_ok=True)
        return target
    for name, text in TEXT_FILES.items():
        safe_path(name).write_text(text, encoding='utf-8')
    with zipfile.ZipFile(io.BytesIO(resource_bytes())) as archive:
        for name in archive.namelist():
            safe_path(name).write_bytes(archive.read(name))
    return destination


def demo():
    core = types.ModuleType('meow_demo_core')
    exec(compile(TEXT_FILES['core.py'], 'core.py', 'exec'), core.__dict__)
    month = '2026-10'
    state = core.apply_action(core.empty_state(), 'budget', {'month': month, 'value': '2000'})
    state = core.apply_action(state, 'add', {'id': 'demo', 'type': 'expense', 'amount': core.cents('400'),
                                            'category': '餐饮', 'date': month + '-01', 'note': '仅内存演示'})
    return core.analyze(state, month)


def main():
    parser = argparse.ArgumentParser(description='记账喵 1.2.0 完整源码包')
    parser.add_argument('--self-check', action='store_true', help='校验源码语法及所有二进制资源')
    parser.add_argument('--demo', action='store_true', help='运行不保存数据的预算与账单演示')
    parser.add_argument('--extract', metavar='DIRECTORY', help='展开为标准多文件源码目录')
    args, desktop_args = parser.parse_known_args()
    if args.self_check:
        print(json.dumps(self_check(), ensure_ascii=False, indent=2))
        return
    if args.demo:
        print(json.dumps(demo(), ensure_ascii=False, indent=2))
        return
    if args.extract:
        self_check()
        print(extract_source(args.extract))
        return
    if sys.platform != 'win32':
        raise SystemExit('桌面 GUI 需在 Windows 运行；可使用 --demo、--self-check 或 --extract。')
    if importlib.util.find_spec('webview') is None:
        raise SystemExit('请先安装依赖：python -m pip install pywebview==6.2.1')
    cache = Path(os.environ.get('LOCALAPPDATA', str(Path.home()))) / 'MeowLedgerSource' / (VERSION + '-' + ASSET_SHA256[:10])
    directory = extract_source(cache)
    sys.path.insert(0, str(directory))
    sys.argv = [str(directory / 'desktop.py'), *desktop_args]
    runpy.run_path(str(directory / 'desktop.py'), run_name='__main__')


if __name__ == '__main__':
    main()
